import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_conv3d(
    torch::Tensor input,
    torch::Tensor weight,
    int64_t stride,
    int64_t padding,
    int64_t dilation,
    int64_t groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Cooperative tiled 3D convolution kernel.
// Each block computes a TILE_H x TILE_W spatial tile of the output, for a
// fixed (batch, output-depth) pair, across all output channels of one group.
// The needed input patch (for all input channels in the group and the K
// depth taps) is staged into shared memory once per group, and the kernel
// weights are staged into shared memory once per block, then reused across
// all output channels and all threads in the tile.
__global__ void conv3d_tiled_kernel(
    const float* __restrict__ in_ptr,
    const float* __restrict__ w_ptr,
    float* __restrict__ out_ptr,
    int N, int Cin, int D, int H, int W,
    int Cout, int K,
    int Dout, int Hout, int Wout,
    int stride, int padding, int dilation,
    int groups, int Cin_per_group, int Cout_per_group,
    int TILE_H, int TILE_W)
{
    // CuTe tensors over global memory (row-major / contiguous layouts).
    auto in_shape  = make_shape(N, Cin, D, H, W);
    auto in_stride = make_stride(Cin * D * H * W, D * H * W, H * W, W, 1);
    Tensor gIn = make_tensor(make_gmem_ptr(in_ptr), make_layout(in_shape, in_stride));

    auto w_shape  = make_shape(Cout, Cin_per_group, K, K, K);
    auto w_stride = make_stride(Cin_per_group * K * K * K, K * K * K, K * K, K, 1);
    Tensor gW = make_tensor(make_gmem_ptr(w_ptr), make_layout(w_shape, w_stride));

    auto out_shape  = make_shape(N, Cout, Dout, Hout, Wout);
    auto out_stride = make_stride(Cout * Dout * Hout * Wout, Dout * Hout * Wout, Hout * Wout, Wout, 1);
    Tensor gOut = make_tensor(make_gmem_ptr(out_ptr), make_layout(out_shape, out_stride));

    const int TH = (TILE_H - 1) * stride + (K - 1) * dilation + 1;
    const int TW = (TILE_W - 1) * stride + (K - 1) * dilation + 1;

    extern __shared__ float smem[];
    const int weight_elems = Cout * Cin_per_group * K * K * K;
    float* s_weight = smem;
    float* s_input  = smem + weight_elems;

    const int bz = blockIdx.z;
    const int n  = bz / Dout;
    const int od = bz % Dout;

    const int ow0 = blockIdx.x * TILE_W;
    const int oh0 = blockIdx.y * TILE_H;

    const int tw = threadIdx.x;
    const int th = threadIdx.y;
    const int tid = th * TILE_W + tw;
    const int nthreads = TILE_H * TILE_W;

    // Load full weight tensor into shared memory once (contiguous copy).
    for (int i = tid; i < weight_elems; i += nthreads) {
        s_weight[i] = w_ptr[i];
    }

    const int base_h = oh0 * stride - padding;
    const int base_w = ow0 * stride - padding;

    const int oh = oh0 + th;
    const int ow = ow0 + tw;
    const bool valid_out = (oh < Hout) && (ow < Wout);

    const int input_tile_elems = Cin_per_group * K * TH * TW;

    for (int g = 0; g < groups; ++g) {
        __syncthreads();

        // Cooperative load of the input patch needed for this group.
        for (int i = tid; i < input_tile_elems; i += nthreads) {
            int rem = i;
            const int lw = rem % TW; rem /= TW;
            const int lh = rem % TH; rem /= TH;
            const int kd = rem % K;  rem /= K;
            const int cin_local = rem;

            const int id = od * stride - padding + kd * dilation;
            const int ih = base_h + lh;
            const int iw = base_w + lw;

            float val = 0.f;
            if (id >= 0 && id < D && ih >= 0 && ih < H && iw >= 0 && iw < W) {
                const int cin = g * Cin_per_group + cin_local;
                val = gIn(n, cin, id, ih, iw);
            }
            s_input[i] = val;
        }

        __syncthreads();

        if (valid_out) {
            for (int oc_local = 0; oc_local < Cout_per_group; ++oc_local) {
                const int oc = g * Cout_per_group + oc_local;
                float acc = 0.f;
                for (int cin_local = 0; cin_local < Cin_per_group; ++cin_local) {
                    for (int kd = 0; kd < K; ++kd) {
                        for (int kh = 0; kh < K; ++kh) {
                            const int lh = th * stride + kh * dilation;
                            for (int kw = 0; kw < K; ++kw) {
                                const int lw = tw * stride + kw * dilation;
                                const int s_idx = ((cin_local * K + kd) * TH + lh) * TW + lw;
                                acc += s_input[s_idx] * gW(oc, cin_local, kd, kh, kw);
                            }
                        }
                    }
                }
                gOut(n, oc, od, oh, ow) = acc;
            }
        }
    }
}

torch::Tensor cute_conv3d(
    torch::Tensor input,
    torch::Tensor weight,
    int64_t stride,
    int64_t padding,
    int64_t dilation,
    int64_t groups)
{
    TORCH_CHECK(input.is_cuda() && weight.is_cuda(), "tensors must be CUDA");
    TORCH_CHECK(input.dim() == 5, "input must be 5D (N,C,D,H,W)");
    TORCH_CHECK(weight.dim() == 5, "weight must be 5D (Cout,Cin/groups,K,K,K)");
    TORCH_CHECK(input.scalar_type() == at::kFloat && weight.scalar_type() == at::kFloat,
                "only float32 supported");

    auto in_c = input.contiguous();
    auto w_c  = weight.contiguous();

    const int N    = (int)in_c.size(0);
    const int Cin  = (int)in_c.size(1);
    const int D    = (int)in_c.size(2);
    const int H    = (int)in_c.size(3);
    const int W    = (int)in_c.size(4);

    const int Cout = (int)w_c.size(0);
    const int Cin_per_group = (int)w_c.size(1);
    const int K    = (int)w_c.size(2);

    const int s = (int)stride;
    const int p = (int)padding;
    const int d = (int)dilation;
    const int g = (int)groups;
    const int Cout_per_group = Cout / g;

    const int Dout = (D + 2 * p - d * (K - 1) - 1) / s + 1;
    const int Hout = (H + 2 * p - d * (K - 1) - 1) / s + 1;
    const int Wout = (W + 2 * p - d * (K - 1) - 1) / s + 1;

    auto out = torch::empty({N, Cout, Dout, Hout, Wout}, in_c.options());

    const int TILE_H = 16;
    const int TILE_W = 16;

    dim3 block(TILE_W, TILE_H);
    dim3 grid((Wout + TILE_W - 1) / TILE_W,
              (Hout + TILE_H - 1) / TILE_H,
              (unsigned int)(N * Dout));

    const int TH = (TILE_H - 1) * s + (K - 1) * d + 1;
    const int TW = (TILE_W - 1) * s + (K - 1) * d + 1;

    const size_t weight_elems = (size_t)Cout * Cin_per_group * K * K * K;
    const size_t input_tile_elems = (size_t)Cin_per_group * K * TH * TW;
    const size_t smem_bytes = (weight_elems + input_tile_elems) * sizeof(float);

    if (smem_bytes > 48 * 1024) {
        cudaFuncSetAttribute(conv3d_tiled_kernel,
                              cudaFuncAttributeMaxDynamicSharedMemorySize,
                              (int)smem_bytes);
    }

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    conv3d_tiled_kernel<<<grid, block, smem_bytes, stream>>>(
        in_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        out.data_ptr<float>(),
        N, Cin, D, H, W,
        Cout, K,
        Dout, Hout, Wout,
        s, p, d,
        g, Cin_per_group, Cout_per_group,
        TILE_H, TILE_W);

    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE conv3d launch failed");
    return out;
}
"""

cute_ext = load_inline(
    name="cute_conv3d_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_conv3d"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "-I/workspace/cutegen_test/cutegen/cutlass/include"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False) -> None:
        super().__init__()
        self.conv3d = nn.Conv3d(in_channels, out_channels,
                                 (kernel_size, kernel_size, kernel_size),
                                 stride=stride, padding=padding, dilation=dilation,
                                 groups=groups, bias=bias)
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        weight = self.conv3d.weight
        conv = self.conv3d
        stride = conv.stride[0]
        padding = conv.padding[0]
        dilation = conv.dilation[0]
        groups = conv.groups

        x_f = x.float().cuda() if not x.is_cuda else x.float()
        w_f = weight.float()

        out = self._ext.cute_conv3d(x_f, w_f, stride, padding, dilation, groups)

        if conv.bias is not None:
            out = out + conv.bias.view(1, -1, 1, 1, 1)

        return out.to(x.dtype)

